fn material() -> [u8; 36] {
    [0x31; 36]
}

// This helper deliberately authenticates arbitrary synthetic malformed plaintext.
// It bypasses only the proposed role validator, never a production API.
fn fixture_blob(value: &[u8], context: &[u8]) -> Vec<u8> {
    let key = material();
    let mut nonce = [0u8; 12];
    nonce[..4].copy_from_slice(&key[32..]);
    nonce[4..].copy_from_slice(&19u64.to_be_bytes());
    let binding = context_binding(&SystemProvider, context);
    let n = value.len() as u32;
    let encrypted = SystemProvider
        .chacha20poly1305_seal(
            key[..32].try_into().unwrap(),
            &nonce,
            &associated_data(&binding, n),
            value,
        )
        .unwrap();
    let mut blob = vec![1];
    blob.extend_from_slice(&1u16.to_be_bytes());
    blob.extend_from_slice(&nonce);
    blob.extend_from_slice(&binding);
    blob.extend_from_slice(&n.to_be_bytes());
    blob.extend_from_slice(&encrypted);
    blob
}

#[test]
fn spqr_literal_schemas_round_trip_and_keep_the_existing_envelope() {
    let fixtures = fixtures();
    assert_eq!(fixtures[0].0.len(), 233);
    assert_eq!(fixtures[2].0.len(), 1309);
    assert_eq!(fixtures[2].1.len(), 331);
    assert_eq!(fixtures[2].3.len(), 3524);
    for (chain_context, chains, skip_context, skipped) in fixtures {
        for (context, plaintext) in [(chain_context, chains), (skip_context, skipped)] {
            let blob = seal(&SystemProvider, &plaintext, &material(), 19, &context)
                .expect("valid independently pinned SPQR map/context must seal");
            assert_eq!(blob, fixture_blob(&plaintext, &context));
            let restored = open(
                &SystemProvider,
                &blob,
                &material(),
                &context,
                ResourceKind::SecretMap,
            )
            .expect("valid typed SPQR blob must restore");
            assert_eq!(&*restored, plaintext);
        }
    }
}

#[test]
fn spqr_each_bound_context_field_is_authenticated_and_roles_are_distinct() {
    let (context, plaintext, other_role, _) = fixtures().remove(0);
    let blob = fixture_blob(&plaintext, &context);
    // Account, device, session, component object, revision, direction, L/K,
    // transition, descriptor and public slot/counter metadata.
    for offset in [1usize, 33, 49, 81, 122, 124, 132, 140, 141, 173, 222, 231] {
        let mut changed = context.clone();
        changed[offset] ^= 1;
        assert_eq!(
            open(
                &SystemProvider,
                &blob,
                &material(),
                &changed,
                ResourceKind::SecretMap
            )
            .err()
            .unwrap()
            .tag,
            CryptoErrorTag::AuthenticationFailed
        );
    }
    assert_eq!(
        open(
            &SystemProvider,
            &blob,
            &material(),
            &other_role,
            ResourceKind::SecretMap
        )
        .err()
        .unwrap()
        .tag,
        CryptoErrorTag::AuthenticationFailed
    );
    assert!(open(
        &SystemProvider,
        &blob,
        &material(),
        &context,
        ResourceKind::SecretBytes
    )
    .is_err());
}

#[test]
fn spqr_authenticated_private_schema_failures_do_not_become_valid_maps() {
    let (context, original, _, _) = fixtures().remove(0);
    let mut candidates = Vec::new();
    let mut wrong_capacity = original.clone();
    wrong_capacity[1] = 64;
    candidates.push(wrong_capacity);
    let mut unknown_root = original.clone();
    unknown_root[10] = 2;
    candidates.push(unknown_root);
    let mut wrong_value_size = original.clone();
    wrong_value_size[9] = 31;
    candidates.push(wrong_value_size);
    let mut missing_root = original.clone();
    missing_root.drain(4..43);
    missing_root[3] = 2;
    candidates.push(missing_root);
    let mut trailing = original.clone();
    trailing.push(0);
    candidates.push(trailing);
    for candidate in candidates {
        assert!(seal(&SystemProvider, &candidate, &material(), 19, &context).is_err());
        let authenticated = fixture_blob(&candidate, &context);
        assert!(open(
            &SystemProvider,
            &authenticated,
            &material(),
            &context,
            ResourceKind::SecretMap
        )
        .is_err());
    }
}

#[test]
fn spqr_context_truncation_tail_and_p1_slot_index_invariants_fail_closed() {
    for (context, plaintext, skipped_context, skipped) in fixtures() {
        for (context, plaintext) in [(context, plaintext), (skipped_context, skipped)] {
            for length in [0usize, 122, 123, 232, context.len() - 1] {
                assert!(seal(
                    &SystemProvider,
                    &plaintext,
                    &material(),
                    19,
                    &context[..length]
                )
                .is_err());
            }
            let mut tail = context.clone();
            tail.push(0);
            assert!(seal(&SystemProvider, &plaintext, &material(), 19, &tail).is_err());
            for (offset, value) in [(123usize, 2u8), (124, 2), (205, 0), (214, 2), (223, 0)] {
                let mut changed = context.clone();
                changed[offset] = value;
                assert!(seal(&SystemProvider, &plaintext, &material(), 19, &changed).is_err());
            }
        }
    }
}

#[test]
fn spqr_map_insertion_order_is_not_public_metadata_order() {
    for (c, m, s, k) in fixtures() {
        for (context, map) in [(c, m), (s, k)] {
            let count = u16::from_be_bytes(map[2..4].try_into().unwrap()) as usize;
            let mut entries = Vec::new();
            let mut offset = 4;
            for _ in 0..count {
                let names =
                    u16::from_be_bytes(map[offset..offset + 2].try_into().unwrap()) as usize;
                let values =
                    u32::from_be_bytes(map[offset + 2..offset + 6].try_into().unwrap()) as usize;
                let end = offset + 6 + names + values;
                entries.push(map[offset..end].to_vec());
                offset = end;
            }
            assert_eq!(offset, map.len());
            let mut reordered = map[..4].to_vec();
            for entry in entries.iter().rev() {
                reordered.extend_from_slice(entry);
            }
            let blob = seal(&SystemProvider, &reordered, &material(), 19, &context).unwrap();
            assert_eq!(
                &*open(
                    &SystemProvider,
                    &blob,
                    &material(),
                    &context,
                    ResourceKind::SecretMap
                )
                .unwrap(),
                reordered
            );
        }
    }
}

#[test]
fn spqr_future_used_chains_multiple_active_sends_and_selected_as_skip_are_refused() {
    let (context, map, _, _) = fixtures().remove(2);
    for offset in [274usize, 283, 248] {
        let mut changed = context.clone();
        changed[offset] = 1;
        assert!(seal(&SystemProvider, &map, &material(), 19, &changed).is_err());
    }
    let (_, _, mut context, mut map) = fixtures().remove(1);
    // Keep map/index names consistent but illegally cache the selected count2.
    *context.last_mut().unwrap() = 2;
    map[26] = 2;
    assert!(seal(&SystemProvider, &map, &material(), 19, &context).is_err());
}

// Rearrange synthetic public literal values only; production never decodes values.
fn without_chain(map: &[u8], epoch: u64, direction: Option<u8>) -> Vec<u8> {
    let mut out = map[..4].to_vec();
    let mut at = 4;
    let mut count = 0u16;
    while at < map.len() {
        let n = u16::from_be_bytes(map[at..at + 2].try_into().unwrap()) as usize;
        let v = u32::from_be_bytes(map[at + 2..at + 6].try_into().unwrap()) as usize;
        let end = at + 6 + n + v;
        let name = &map[at + 6..at + 6 + n];
        if !(name.len() == 10
            && name[0] == 1
            && name[1..9] == epoch.to_be_bytes()
            && direction.is_none_or(|d| name[9] == d))
        {
            out.extend_from_slice(&map[at..end]);
            count += 1;
        }
        at = end;
    }
    out[2..4].copy_from_slice(&count.to_be_bytes());
    out
}
#[test]
fn spqr_metadata_refusals_do_not_depend_on_missing_or_extra_map_names() {
    let (initial, map, _, _) = fixtures().remove(0);
    let (mut maximum, max_map, _, _) = fixtures().remove(2);
    maximum.truncate(285);
    maximum[284] = 0;
    let mut cases = Vec::new();
    let mut c = initial;
    c[223] = 0;
    cases.push(("mandatory receive", c, without_chain(&map, 0, Some(1))));
    let mut c = maximum.clone();
    c[214] = 0;
    cases.push(("absent used send", c, without_chain(&max_map, 0, Some(0))));
    let mut c = maximum.clone();
    c[240] = 0;
    cases.push((
        "absent current send",
        c,
        without_chain(&max_map, 1, Some(0)),
    ));
    let mut c = maximum.clone();
    c.drain(232..258);
    c[205] = 2;
    cases.push(("retained gap", c, without_chain(&max_map, 1, None)));
    let mut c = maximum;
    c[133..141].fill(0);
    c[250..258].fill(0);
    cases.push(("L exceeds K+1", c, max_map));
    for (name, c, m) in cases {
        assert!(
            seal(&SystemProvider, &m, &material(), 19, &c).is_err(),
            "{name}"
        );
        assert!(
            open(
                &SystemProvider,
                &fixture_blob(&m, &c),
                &material(),
                &c,
                ResourceKind::SecretMap
            )
            .is_err(),
            "{name}"
        );
    }
}
#[derive(Default)]
struct ForbidOrdinary(std::sync::atomic::AtomicUsize);
impl CryptoProvider for ForbidOrdinary {
    fn fill_random(&self, _: &mut [u8]) -> Result<(), crate::crypto::provider::ProviderError> {
        Err(crate::crypto::provider::ProviderError::EntropyUnavailable)
    }
    fn chacha20poly1305_seal(
        &self,
        _: &[u8; 32],
        _: &[u8; 12],
        _: &[u8],
        _: &[u8],
    ) -> Result<Vec<u8>, crate::crypto::provider::ProviderError> {
        self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        Err(crate::crypto::provider::ProviderError::InternalFailure)
    }
    fn chacha20poly1305_open(
        &self,
        _: &[u8; 32],
        _: &[u8; 12],
        _: &[u8],
        _: &mut Zeroizing<Vec<u8>>,
    ) -> Result<(), crate::crypto::provider::ProviderError> {
        self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        Err(crate::crypto::provider::ProviderError::InternalFailure)
    }
}
#[test]
fn spqr_detached_paths_and_internal_generic_refusal_never_use_ordinary_provider() {
    let p = ForbidOrdinary::default();
    let (c, m, _, _) = fixtures().remove(0);
    let b = seal_value(&p, &m, &material(), 19, &c, ResourceKind::SecretMap)
        .expect("protected internal dispatch");
    assert_eq!(b, fixture_blob(&m, &c));
    assert_eq!(
        &*open(&p, &b, &material(), &c, ResourceKind::SecretMap).unwrap(),
        m
    );
    assert_eq!(
        open_value(&p, &b, &material(), &c, ResourceKind::SecretMap)
            .err()
            .unwrap()
            .tag,
        CryptoErrorTag::UnsupportedOperation
    );
    assert_eq!(p.0.load(std::sync::atomic::Ordering::SeqCst), 0);
}
#[test]
fn spqr_invalid_restore_publishes_nothing_and_valid_restore_one_owned_map() {
    use crate::actor::{Priority, ProcessId};
    crate::mesh_rt_init();
    let mut p = Process::new(ProcessId(915_249), Priority::Normal);
    let key = insert_ephemeral_storage_key_resource(
        &mut p,
        ProtectedBytes::copy_from(&material()).unwrap(),
    )
    .unwrap();
    let (c, m, _, _) = fixtures().remove(0);
    let before = crate::secret::owned_secret_count_for_test(p.pid);
    let mut invalid = m.clone();
    invalid[1] = 64;
    for b in [
        fixture_blob(&invalid, &c),
        {
            let mut b = fixture_blob(&m, &c);
            *b.last_mut().unwrap() ^= 1;
            b
        },
        {
            let b = fixture_blob(&m, &c);
            b[..b.len() - 1].to_vec()
        },
        {
            let mut b = fixture_blob(&m, &c);
            b[15] ^= 1;
            b
        },
        {
            let mut b = fixture_blob(&m, &c);
            b.push(0);
            b
        },
    ] {
        assert!(open_for_process(
            &mut p,
            &SystemProvider,
            &b,
            key,
            &c,
            ResourceKind::SecretMap
        )
        .is_err());
        assert_eq!(crate::secret::owned_secret_count_for_test(p.pid), before);
    }
    let h = open_for_process(
        &mut p,
        &SystemProvider,
        &fixture_blob(&m, &c),
        key,
        &c,
        ResourceKind::SecretMap,
    )
    .expect("one valid protected map");
    assert_eq!(
        crate::secret::owned_secret_count_for_test(p.pid),
        before + 1
    );
    assert_eq!(
        &*prepare_owned_resource(&p, h, ResourceKind::SecretMap)
            .unwrap()
            .bytes,
        m
    );
    crate::secret::destroy_owned(p.pid);
}

fn native_context(bytes: &[u8]) -> Vec<u64> {
    let mut out = vec![0u64; 1 + bytes.len().div_ceil(8)];
    out[0] = bytes.len() as u64;
    unsafe {
        std::slice::from_raw_parts_mut(out.as_mut_ptr().cast::<u8>().add(8), bytes.len())
            .copy_from_slice(bytes)
    };
    out
}
#[test]
fn spqr_bounded_context_fallback_preserves_every_legacy_copy_error() {
    let (base, _, _, _) = fixtures().remove(0);
    for purpose in (1u16..=23).chain([65535]) {
        for length in [0usize, 10, 122, 123, 124, 233, 1309, 1310] {
            let mut c = base.clone();
            c[113..115].copy_from_slice(&purpose.to_be_bytes());
            c.resize(length, 0);
            let native = native_context(&c);
            let p = native.as_ptr().cast::<MeshBytes>();
            let original = unsafe { braid_responder::copy_resource_context(p) }
                .map_err(|e| (e.tag, e.expected, e.actual));
            let actual = unsafe { spqr::copy_resource_context(p) }
                .map_err(|e| (e.tag, e.expected, e.actual));
            assert_eq!(actual, original, "purpose{purpose}/length{length}");
        }
    }
    for purpose in [24u16, 25] {
        let mut c = base.clone();
        c[113..115].copy_from_slice(&purpose.to_be_bytes());
        for n in [233usize, 1309] {
            let mut c = c.clone();
            c.resize(n, 0);
            let native = native_context(&c);
            assert_eq!(
                unsafe { spqr::copy_resource_context(native.as_ptr().cast()) }.unwrap(),
                c
            );
        }
        c.resize(1310, 0);
        let native = native_context(&c);
        let e = unsafe { spqr::copy_resource_context(native.as_ptr().cast()) }
            .err()
            .unwrap();
        assert_eq!(
            (e.tag, e.expected, e.actual),
            (CryptoErrorTag::InvalidLength, 123, 1310)
        );
        let e = spqr::validate_context(&c, ResourceKind::SecretMap.into())
            .err()
            .unwrap();
        assert_eq!(
            (e.tag, e.expected, e.actual),
            (CryptoErrorTag::InvalidLength, 1309, 1310)
        );
    }
}
